/**
 * Builds src/sudoku/fallback-puzzles.ts: a fixed, seeded set per level that the app uses when its
 * pre-generated buffer is empty, so starting a game is always instant. Deterministic: re-running
 * produces the same file. Run with `npx tsx scripts/build-fallback.ts`.
 */
import { writeFileSync } from 'node:fs';
import { generatePuzzle } from '../src/sudoku/generator';
import { LEVELS } from '../src/sudoku/grader';
import { mulberry32 } from '../src/sudoku/rng';

const PER_LEVEL = 24;
const lines: string[] = [
  '/* eslint-disable */',
  '// Generated by scripts/build-fallback.ts. Do not edit by hand.',
  "import type { Level } from './grader';",
  '',
  '/** [givens, solution] pairs per level. */',
  'export const FALLBACK_PUZZLES: Record<Level, readonly (readonly [string, string])[]> = {',
];
for (const [li, level] of LEVELS.entries()) {
  lines.push(`  ${level}: [`);
  for (let i = 0; i < PER_LEVEL; i++) {
    const p = generatePuzzle(level, mulberry32(0x5c0de + li * 1000 + i));
    lines.push(`    ['${p.givens}', '${p.solution}'],`);
  }
  lines.push('  ],');
}
lines.push('};', '');
writeFileSync(new URL('../src/sudoku/fallback-puzzles.ts', import.meta.url), lines.join('\n'));
console.log('wrote', LEVELS.length * PER_LEVEL, 'puzzles');
